fn print_json(value: &serde_json::Value, indent: usize, no_inline: bool) {
    let indent_str = "  ".repeat(indent);

    match value {
        serde_json::Value::Object(map) => {
            if map.is_empty() {
                println!("{}{}", indent_str, "{}");
                return;
            }
            println!("{}{}", indent_str, "{");
            // Collect keys in order from the map
            let mut keys: Vec<_> = map.keys().collect();
            for (i, key) in keys.iter().enumerate() {
                println!("{}  \"{}\": ", indent_str, key);
                print_json(map.get(key).unwrap(), indent + 1, no_inline);
                if i < keys.len() - 1 {
                    println!(",");
                }
            }
            println!("{}{}", indent_str, "}");
        }
