fn process_json(data: &str, raw: bool, slurp: bool, no_inline: bool) {
    if raw {
        println!("{}", data);
        return;
    }

    match serde_json::from_str::<serde_json::Value>(data) {
        Ok(value) => {
            if slurp {
                // For slurp mode, we'd need to handle multiple inputs
                // Simplified for now
            }
            print_json(&value, 0, no_inline);
        }
        Err(e) => {
            eprintln!("Error: invalid JSON: {}", e);
            process::exit(1);
        }
    }
}

fn print_json(value: &serde_json::Value, indent: usize, no_inline: bool) {
    let indent_str = "  ".repeat(indent);

    match value {
        serde_json::Value::Object(map) => {
            if map.is_empty() {
                println!("{}{}", indent_str, "{}");
                return;
            }
            println!("{}{}", indent_str, "{");
            // Collect keys in order from the map
            let mut keys: Vec<_> = map.keys().collect();
            for (i, key) in keys.iter().enumerate() {
                println!("{}  \"{}\": ", indent_str, key);
                print_json(map.get(key).unwrap(), indent + 1, no_inline);
                if i < keys.len() - 1 {
                    println!(",");
                }
            }
            println!("{}{}", indent_str, "}");
        }
        serde_json::Value::Array(arr) => {
            if arr.is_empty() {
                println!("{}{}", indent_str, "[]");
                return;
            }
            println!("{}{}", indent_str, "[");
            for (i, item) in arr.iter().enumerate() {
                print_json(item, indent + 1, no_inline);
                if i < arr.len() - 1 {
                    println!(",");
                }
            }
            println!("{}{}", indent_str, "]");
        }
        serde_json::Value::String(s) => {
            println!("\"{}\"", s);
        }
        serde_json::Value::Number(n) => {
            println!("{}", n);
        }
        serde_json::Value::Bool(b) => {
            println!("{}", b);
        }
        serde_json::Value::Null => {
            println!("null");
        }
    }
}
