+                printed = true;
+                process::exit(0);
+            }
+        }
+    }
+    
+    if !printed {
+        if args.len() == 1 {
+            let mut input = String::new();
+            io::stdin().read_to_string(&mut input).unwrap();
+            println!("{}", input);
+        } else if args.len() > 1 {
+            let filename = &args[1];
+            let input = fs::read_to_string(filename).unwrap();
+            println!("{}", input);
+        }
+    }
+}
