+		fmt.Println("}")
+		fmt.Println()
+	}
+}
+
+func printCompletion(shell string) {
+	fmt.Printf("complete -o filenames -C fx fx\n")
+}
+
+func readInput(files []string) string {
+	if len(files) == 1 {
+		if strings.HasPrefix(files[0], "-") {
+			return readFromStdin()
+		}
+		data, err := os.ReadFile(files[0])
+		if err != nil {
+			fmt.Fprintf(os.Stderr, "\n  %s\n", files[0])
+			os.Exit(1)
+		}
+		return string(data)
+	}
+	return readFromStdin()
+}
+
+func readAllInputs(files []string) string {
+	var result string
+	for _, f := range files {
+		if strings.HasPrefix(f, "-") {
+			result += readFromStdin()
+		} else {
+			data, err := os.ReadFile(f)
+			if err != nil {
+				fmt.Fprintf(os.Stderr, "\n  %s\n", f)
+				os.Exit(1)
+			}
+			result += string(data)
+		}
+	}
+	return result
+}
+
+func readFromStdin() string {
+	reader := bufio.NewReader(os.Stdin)
+	var result string
+	for {
+		line, err := reader.ReadString('\n')
+		if err != nil && err == io.EOF {
+			break
+		}
+		result += line
+	}
+	return result
+}
